+/// Màn Lịch sử (SPEC-lich-su-cham-cong-vieng-tham §4.1): một lượt viếng thăm
+/// và một bản ghi chấm công, đã gộp server + dữ liệu trên máy.
+library;
+
+/// Lượt thăm có thuộc lịch tuyến NGÀY HÔM ĐÓ không (SPEC §3.2b):
+/// - `Trong tuyến` / `Ngoài tuyến` — theo cờ `in_day_route` BE ghi lúc check-in.
+///   KH gán tay, tự tạo, KH tuyến nhưng khác ngày, lượt xin ngoại tuyến đều
+///   KHÔNG thuộc tuyến ngày hôm đó.
+/// - `Chưa rõ tuyến` — lượt cũ trước khi có cờ (`in_day_route = null`): không
+///   suy đoán từ `route_line` (chỉ cho biết KH thuộc tuyến nào đó, không phải
+///   có lịch ngày hôm đó).
+enum VisitSource {
+  route('Trong tuyến'),
+  offroute('Ngoài tuyến'),
+  unknown('Chưa rõ tuyến');
+
+  const VisitSource(this.label);
+  final String label;
+
+  /// Từ `rt.visit/history`: `source = offroute` (xin ngoại tuyến) luôn là
+  /// Ngoài tuyến; còn lại theo `in_day_route` (true/false/null).
+  static VisitSource fromServer({String? source, Object? inDayRoute}) {
+    if (source == 'offroute') return VisitSource.offroute;
+    if (inDayRoute == true) return VisitSource.route;
+    if (inDayRoute == false) return VisitSource.offroute;
+    return VisitSource.unknown;
+  }
+
+  /// Lượt chỉ có ở máy: có lịch tuyến NGÀY check-in và không xin ngoại tuyến
+  /// → route; còn lại → offroute (như BE).
+  static VisitSource infer({required bool isOffroute, required bool inDayRoute}) =>
+      !isOffroute && inDayRoute ? VisitSource.route : VisitSource.offroute;
+}
+
+DateTime? _date(Object? v) =>
+    v is String && v.isNotEmpty ? DateTime.tryParse(v) : null;
+
+int? _int(Object? v) => v is int ? v : (v is num ? v.toInt() : int.tryParse('$v'));
+
+String? _text(Object? v) {
+  final s = v?.toString().trim() ?? '';
+  return s.isEmpty ? null : s;
+}
+
+class VisitHistoryItem {
+  const VisitHistoryItem({
+    required this.clientUuid,
+    required this.customerId,
+    required this.customerName,
+    this.customerAddress,
+    required this.source,
+    required this.status,
+    this.outcome,
+    required this.checkinAt,
+    this.checkoutAt,
+    this.durationMinutes,
+    this.steps = const [],
+    this.note,
+    this.localOnly = false,
+    this.notePending = false,
+  });
+
+  final String clientUuid;
+  final int customerId;
+  final String customerName;
+  final String? customerAddress;
+  final VisitSource source;
+
+  /// 0 mở · 1 đang thực hiện · 2 hoàn tất.
+  final int status;
+  final String? outcome;
+  final DateTime checkinAt;
+  final DateTime? checkoutAt;
+  final int? durationMinutes;
+  final List<String> steps;
+  final String? note;
+
+  /// Chỉ có trên máy (chưa đồng bộ lên server).
+  final bool localOnly;
+
+  /// Ghi chú trên máy mới hơn server (lưu/sửa còn chờ trong outbox).
+  final bool notePending;
+
+  bool get isOpen => checkoutAt == null && status != 2;
+
+  /// Bản server bù dữ liệu trên máy chưa kịp đồng bộ: ghi chú (server chưa
+  /// có) + các bước đã lưu ở máy.
+  VisitHistoryItem withLocal(VisitHistoryItem local) => VisitHistoryItem(
+        clientUuid: clientUuid,
+        customerId: customerId,
+        customerName: customerName,
+        customerAddress: customerAddress ?? local.customerAddress,
+        source: source,
+        status: status,
+        outcome: outcome,
+        checkinAt: checkinAt,
+        checkoutAt: checkoutAt,
+        durationMinutes: durationMinutes,
+        steps: {...steps, ...local.steps}.toList(),
+        note: local.notePending && local.note != null
+            ? local.note
+            : (note ?? local.note),
+        localOnly: localOnly,
+      );
+
+  static VisitHistoryItem? fromJson(Map<String, dynamic> j) {
+    final at = _date(j['checkin_at']);
+    final uuid = _text(j['client_uuid']);
+    final cust = j['customer'] is Map ? j['customer'] as Map : const {};
+    final customerId = _int(cust['id']);
+    if (at == null || uuid == null || customerId == null) return null;
+    return VisitHistoryItem(
+      clientUuid: uuid,
+      customerId: customerId,
+      customerName: _text(cust['name']) ?? 'KH #$customerId',
+      customerAddress: _text(cust['address']),
+      source: VisitSource.fromServer(
+        source: j['source']?.toString(),
+        inDayRoute: j['in_day_route'],
+      ),
+      status: _int(j['status']) ?? 0,
+      outcome: _text(j['outcome']),
+      checkinAt: at,
+      checkoutAt: _date(j['checkout_at']),
+      durationMinutes: _int(j['duration_minutes']),
+      steps: (j['steps'] is List)
+          ? (j['steps'] as List).map((e) => '$e').toList()
+          : const [],
+      note: _text(j['note']),
+    );
+  }
+}
+
+/// shift = một ca (vào–ra) · leave = đơn xin nghỉ.
+enum AttendanceKind { shift, leave }
+
+class AttendanceHistoryItem {
+  const AttendanceHistoryItem({
+    required this.clientUuid,
+    required this.kind,
+    this.checkInAt,
+    this.checkOutAt,
+    this.workedMinutes,
+    this.leaveType,
+    this.leaveFrom,
+    this.leaveTo,
+    this.reason,
+    this.status = 0,
+    this.localOnly = false,
+    this.checkOutLocalOnly = false,
+  });
+
+  final String clientUuid;
+  final AttendanceKind kind;
+  final DateTime? checkInAt;
+  final DateTime? checkOutAt;
+  final int? workedMinutes;
+  final String? leaveType;
+  final DateTime? leaveFrom;
+  final DateTime? leaveTo;
+  final String? reason;
+
+  /// Trạng thái duyệt (đơn nghỉ): 0 chờ duyệt · 1 đã duyệt · 2 từ chối.
+  final int status;
+  final bool localOnly;
+
+  /// Giờ ra lấy từ máy, server chưa nhận.
+  final bool checkOutLocalOnly;
+
+  /// Mốc sắp xếp/nhóm theo ngày.
+  DateTime get sortAt =>
+      checkInAt ?? leaveFrom ?? DateTime.fromMillisecondsSinceEpoch(0);
+
+  AttendanceHistoryItem copyWith({
+    DateTime? checkOutAt,
+    int? workedMinutes,
+    bool? checkOutLocalOnly,
+  }) =>
+      AttendanceHistoryItem(
+        clientUuid: clientUuid,
+        kind: kind,
+        checkInAt: checkInAt,
+        checkOutAt: checkOutAt ?? this.checkOutAt,
+        workedMinutes: workedMinutes ?? this.workedMinutes,
+        leaveType: leaveType,
+        leaveFrom: leaveFrom,
+        leaveTo: leaveTo,
+        reason: reason,
+        status: status,
+        localOnly: localOnly,
+        checkOutLocalOnly: checkOutLocalOnly ?? this.checkOutLocalOnly,
+      );
+
+  static AttendanceHistoryItem? fromJson(Map<String, dynamic> j) {
+    final uuid = _text(j['client_uuid']);
+    if (uuid == null) return null;
+    final isLeave = j['type'] == 'leave';
+    return AttendanceHistoryItem(
+      clientUuid: uuid,
+      kind: isLeave ? AttendanceKind.leave : AttendanceKind.shift,
+      checkInAt: _date(j['check_in_at']),
+      checkOutAt: _date(j['check_out_at']),
+      workedMinutes: _int(j['worked_minutes']),
+      leaveType: _text(j['leave_type']),
+      leaveFrom: _date(j['leave_from']),
+      leaveTo: _date(j['leave_to']),
+      reason: _text(j['reason']),
+      status: _int(j['status']) ?? 0,
+    );
+  }
+}
+
+/// Một trang lịch sử viếng thăm. [offline] = không gọi được server, chỉ có
+/// dữ liệu trên máy.
+class VisitHistoryPage {
+  const VisitHistoryPage({
+    required this.items,
+    required this.total,
+    this.serverCount = 0,
+    this.offline = false,
+  });
+
+  final List<VisitHistoryItem> items;
+
+  /// Tổng số lượt trên server (để "Tải thêm").
+  final int total;
+
+  /// Số lượt của trang này lấy từ server — cộng dồn làm `offset` trang sau.
+  final int serverCount;
+  final bool offline;
+}
+
+class AttendanceHistoryPage {
+  const AttendanceHistoryPage({required this.items, this.offline = false});
+
+  final List<AttendanceHistoryItem> items;
+  final bool offline;
+}
+
+/// Ghi chú lần thăm trước tại một điểm bán (bước Ghi chú §4.2).
+class PastVisitNote {
+  const PastVisitNote({
+    required this.visitUuid,
+    required this.at,
+    required this.text,
+  });
+
+  final String visitUuid;
+  final DateTime at;
+  final String text;
+}

