+  void _snack(String text, Color color) {
+    ScaffoldMessenger.of(context).showSnackBar(
+      SnackBar(content: Text(text), backgroundColor: color),
+    );
+  }
+
+  /// SPEC-tra-cuu-mst-sua-kh §3.1–3.3: tra mã trong ô [field] → so với form
+  /// → hộp thoại đề xuất. Chỉ ĐIỀN form, không tự gửi.
+  Future<void> _runLookup(TaxCodeKind field) async {
+    final ctrl = field == TaxCodeKind.cccd ? _cccdCtrl : _taxCtrl;
+    final raw = ctrl.text.trim();
+    if (raw.isEmpty) {
+      _snack('Nhập MST/CCCD để tra cứu', Colors.orange.shade800);
+      return;
+    }
+    final parsed = classifyTaxCode(raw);
+    final String? formatError;
+    if (parsed == null) {
+      formatError = field == TaxCodeKind.cccd
+          ? CustomerPilotService.cccdError
+          : 'MST 10 hoặc 13 số (chi nhánh dạng 0123456789-001)';
+    } else if (parsed.kind != field) {
+      formatError = field == TaxCodeKind.taxCode
+          ? 'Mã 12 số là CCCD — nhập vào ô CCCD'
+          : CustomerPilotService.cccdError;
+    } else {
+      formatError = null;
+    }
+    if (formatError != null || parsed == null) {
+      _snack(formatError ?? 'Mã không hợp lệ', Colors.red.shade700);
+      return;
+    }
+
+    setState(() => _looking = field);
+    TaxLookupResult r;
+    try {
+      r = await _taxLookupApi.lookup(parsed.code, parsed.kind);
+    } on FormatException catch (e) {
+      if (!mounted) return;
+      setState(() => _looking = null);
+      _snack(e.message, Colors.red.shade700);
+      return;
+    }
+    if (!mounted) return;
+    setState(() => _looking = null);
+
+    if (!r.found) {
+      _snack(r.missMessage, Colors.orange.shade800);
+      return;
+    }
+    final suggestions = taxLookupSuggestions(_identitySnapshot(), r);
+    final warnings =
+        taxLookupWarnings(r, customerCode: widget.customer.code);
+    if (suggestions.isEmpty && warnings.isEmpty) {
+      _snack('Thông tin KH đã khớp dữ liệu tra cứu', Colors.green);
+      return;
+    }
+    final picked = await showTaxLookupUpdateDialog(
+      context,
+      result: r,
+      suggestions: suggestions,
+      warnings: warnings,
+    );
+    if (!mounted || picked.isEmpty) return;
+    setState(() {
+      // Mã chuẩn hoá (13 số → 10-3) ghi lại vào ô vừa tra.
+      ctrl.text = r.code.isNotEmpty ? r.code : parsed.code;
+      _applySuggestions(r, picked);
+    });
+    _formKey.currentState?.validate();
+    _snack(
+      'Đã điền ${picked.length} mục — bấm Gửi yêu cầu sửa để gửi duyệt',
+      Colors.green,
+    );
+  }
+
+  CustomerIdentitySnapshot _identitySnapshot() => CustomerIdentitySnapshot(
+        name: _nameCtrl.text,
+        billingName: _billingCtrl.text,
+        owner: _contactPersonCtrl.text,
+        line1: _line1Ctrl.text,
+        wardId: _ward?.id,
+        provinceName: _province?.name ?? '',
+        wardName: _ward?.name ?? '',
+      );
+
+  void _applySuggestions(TaxLookupResult r, Set<TaxSuggestField> picked) {
+    final name = r.name;
+    if (name != null) {
+      if (picked.contains(TaxSuggestField.billingName)) _billingCtrl.text = name;
+      if (picked.contains(TaxSuggestField.owner)) {
+        _contactPersonCtrl.text = name;
+      }
+      if (picked.contains(TaxSuggestField.name)) _nameCtrl.text = name;
+    }
+    final province = r.province;
+    final ward = r.ward;
+    final line1 = r.line1;
+    if (picked.contains(TaxSuggestField.address) &&
+        province != null &&
+        ward != null &&
+        line1 != null) {
+      _province = AddressEntity(id: province.id, name: province.name);
+      _ward = AddressEntity(id: ward.id, name: ward.name);
+      _provinceCtrl.text = province.name;
+      _wardCtrl.text = ward.name;
+      _line1Ctrl.text = line1;
+    }
+  }
+
+  Widget _lookupButton(TaxCodeKind field) {
+    if (_looking == field) {
+      return const Padding(
+        padding: EdgeInsets.all(12),
+        child: SizedBox(
+          width: 20,
+          height: 20,
+          child: CircularProgressIndicator(strokeWidth: 2),
+        ),
+      );
