+/// Tab mở sẵn khi vào màn Lịch sử.
+enum HistoryTab { visits, attendance }
+
+/// Bộ lọc thời gian: Hôm nay · Tháng này · Chọn ngày (SPEC §4.1, §8.3).
+enum HistoryPeriod { today, thisMonth, pickedDay }
+
+final _dayKey = DateFormat('yyyy-MM-dd');
+final _hm = DateFormat('HH:mm');
