+
+/// Màn **Lịch sử**: viếng thăm (cả điểm trong tuyến lẫn điểm tự chọn từ danh
+/// sách KH) và chấm công của chính sale.
+class HistoryScreen extends StatelessWidget {
+  const HistoryScreen({
+    super.key,
+    this.initialTab = HistoryTab.visits,
+    this.service,
+    this.clock,
+  });
+
+  final HistoryTab initialTab;
+  final HistoryService? service;
+  final DateTime Function()? clock;
+
+  @override
