+          _VisitsTab(service: svc, clock: now),
+          _AttendanceTab(service: svc, clock: now),
+        ]),
+      ),
+    );
+  }
+}
+
+/// Chip chọn kỳ + ngày đã chọn. Đổi kỳ → gọi [onChanged] với khoảng mới.
+class _PeriodBar extends StatelessWidget {
+  const _PeriodBar({
+    required this.period,
+    required this.picked,
+    required this.clock,
+    required this.onChanged,
+  });
+
+  final HistoryPeriod period;
+  final DateTime? picked;
+  final DateTime Function() clock;
+  final void Function(HistoryPeriod period, DateTime? picked) onChanged;
+
+  Future<void> _pick(BuildContext context) async {
+    final now = clock();
+    final d = await showDatePicker(
+      context: context,
+      initialDate: picked ?? now,
+      firstDate: DateTime(now.year - 1, now.month, now.day),
+      lastDate: now,
+    );
+    if (d != null) onChanged(HistoryPeriod.pickedDay, d);
+  }
+
+  @override
+  Widget build(BuildContext context) {
+    return Padding(
+      padding: const EdgeInsets.fromLTRB(12, 8, 12, 4),
+      child: Wrap(spacing: 8, children: [
+        ChoiceChip(
+          label: const Text('Hôm nay'),
+          selected: period == HistoryPeriod.today,
+          onSelected: (_) => onChanged(HistoryPeriod.today, null),
+        ),
+        ChoiceChip(
+          label: const Text('Tháng này'),
+          selected: period == HistoryPeriod.thisMonth,
+          onSelected: (_) => onChanged(HistoryPeriod.thisMonth, null),
+        ),
+        ChoiceChip(
+          key: const Key('history_pick_day'),
+          avatar: const Icon(Icons.calendar_today, size: 16),
+          label: Text(period == HistoryPeriod.pickedDay && picked != null
+              ? DateFormat('dd/MM/yyyy').format(picked!)
+              : 'Chọn ngày'),
+          selected: period == HistoryPeriod.pickedDay,
+          onSelected: (_) => _pick(context),
+        ),
+      ]),
+    );
+  }
+}
