+DayRange rangeFor(HistoryPeriod p, DateTime? picked, DateTime now) =>
+    switch (p) {
+      HistoryPeriod.today => DayRange.day(now),
+      HistoryPeriod.thisMonth => DayRange.thisMonth(now),
+      HistoryPeriod.pickedDay => DayRange.day(picked ?? now),
+    };
+
+Widget _offlineBanner() => Container(
+      key: const Key('history_offline'),
+      width: double.infinity,
+      color: Colors.amber.shade50,
+      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
+      child: Text('Đang xem dữ liệu trên máy — có thể thiếu',
+          style: TextStyle(color: Colors.amber.shade900, fontSize: 12.5)),
+    );
+
+const _weekdays = ['Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy', 'Chủ nhật'];
+
+/// `Thứ Hai, 10/06/2026` — tự ghép thứ, không phụ thuộc locale intl.
+String dayHeaderLabel(DateTime d) =>
+    '${_weekdays[d.weekday - 1]}, ${DateFormat('dd/MM/yyyy').format(d)}';
+
+Widget _dayHeaderTile(DateTime d) => Padding(
+      padding: const EdgeInsets.fromLTRB(16, 14, 16, 4),
+      child: Text(
+        dayHeaderLabel(d),
+        style: TextStyle(
+            fontWeight: FontWeight.bold, color: Colors.blueGrey.shade700),
+      ),
+    );
+
+Widget _tag(String text, Color color) => Container(
+      margin: const EdgeInsets.only(right: 6, top: 4),
+      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
+      decoration: BoxDecoration(
+        color: color.withValues(alpha: 0.1),
+        borderRadius: BorderRadius.circular(6),
+      ),
+      child: Text(text,
+          style: TextStyle(
+              color: color, fontSize: 11.5, fontWeight: FontWeight.w600)),
+    );
+
+Color _sourceColor(VisitSource s) => switch (s) {
+      VisitSource.route => Colors.blue.shade700,
+      VisitSource.offroute => Colors.orange.shade800,
+      VisitSource.unknown => Colors.grey.shade600,
+    };
+
+/// Nhóm theo ngày (giờ máy) giữ thứ tự mới nhất trước.
+List<Widget> _grouped<T>(
+  List<T> items,
+  DateTime Function(T) at,
+  Widget Function(T) row,
+) {
+  final out = <Widget>[];
+  String? last;
+  for (final it in items) {
+    final d = at(it).toLocal();
+    final k = _dayKey.format(d);
+    if (k != last) {
+      out.add(_dayHeaderTile(d));
+      last = k;
+    }
+    out.add(row(it));
+  }
+  return out;
+}
