+class _VisitsTabState extends State<_VisitsTab>
+    with AutomaticKeepAliveClientMixin {
+  HistoryPeriod _period = HistoryPeriod.today;
+  DateTime? _picked;
+  final List<VisitHistoryItem> _items = [];
+  int _total = 0;
+  int _offset = 0;
+  bool _offline = false;
+  bool _loading = true;
+  bool _loadingMore = false;
+  int _generation = 0;
+
+  @override
+  bool get wantKeepAlive => true;
+
+  @override
+  void initState() {
+    super.initState();
+    _load();
+  }
+
+  DayRange get _range => rangeFor(_period, _picked, widget.clock());
+
+  Future<void> _load() async {
+    final gen = ++_generation;
+    setState(() => _loading = true);
+    final page = await widget.service.visits(_range);
+    if (!mounted || gen != _generation) return;
+    setState(() {
+      _items
+        ..clear()
+        ..addAll(page.items);
+      _total = page.total;
+      _offset = page.serverCount;
+      _offline = page.offline;
+      _loading = false;
+    });
+  }
+
+  Future<void> _loadMore() async {
+    final gen = _generation;
+    setState(() => _loadingMore = true);
+    final page = await widget.service.visits(_range, offset: _offset);
+    if (!mounted || gen != _generation) return;
+    setState(() {
+      final known = _items.map((e) => e.clientUuid).toSet();
+      _items.addAll(page.items.where((e) => !known.contains(e.clientUuid)));
+      _offset += page.serverCount;
+      _total = page.total;
+      _loadingMore = false;
+      // Mất mạng giữa chừng → dừng tải thêm.
+      if (page.offline) _total = _offset;
+    });
+  }
+
+  void _onPeriod(HistoryPeriod p, DateTime? picked) {
+    setState(() {
+      _period = p;
+      _picked = picked;
+    });
+    _load();
+  }
+
+  @override
+  Widget build(BuildContext context) {
+    super.build(context);
+    return Column(children: [
+      _PeriodBar(
+          period: _period,
+          picked: _picked,
+          clock: widget.clock,
+          onChanged: _onPeriod),
+      if (_offline) _offlineBanner(),
+      Expanded(child: _body()),
+    ]);
+  }
+
+  Widget _body() {
+    if (_loading) return const Center(child: CircularProgressIndicator());
+    if (_items.isEmpty) {
+      return RefreshIndicator(
+        onRefresh: _load,
+        child: ListView(children: const [
+          SizedBox(height: 80),
+          Center(child: Text('Chưa có lượt viếng thăm trong kỳ này')),
+        ]),
+      );
+    }
+    final canMore = !_offline && _offset < _total;
+    return RefreshIndicator(
+      onRefresh: _load,
+      child: ListView(
+        padding: const EdgeInsets.only(bottom: 24),
+        children: [
+          Padding(
+            padding: const EdgeInsets.fromLTRB(16, 4, 16, 0),
+            child: Text(
+              '${_items.length} lượt viếng thăm',
+              style: TextStyle(color: Colors.grey.shade700, fontSize: 12.5),
