+          ..._grouped(_items, (v) => v.checkinAt, _visitRow),
+          if (canMore)
+            Padding(
+              padding: const EdgeInsets.all(12),
+              child: OutlinedButton(
+                key: const Key('history_load_more'),
+                onPressed: _loadingMore ? null : _loadMore,
+                child: Text(_loadingMore ? 'Đang tải…' : 'Tải thêm'),
+              ),
+            ),
+        ],
+      ),
+    );
+  }
+
+  String _timeLine(VisitHistoryItem v) {
+    final inAt = _hm.format(v.checkinAt.toLocal());
+    if (v.isOpen) return '$inAt → …';
+    final out = v.checkoutAt != null ? _hm.format(v.checkoutAt!.toLocal()) : '—';
+    final mins = v.durationMinutes != null ? ' · ${v.durationMinutes} phút' : '';
