+    return Card(
+      margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
+      child: ListTile(
+        leading: Icon(Icons.fingerprint, color: Colors.green.shade700),
+        title: Text(open ? 'Vào $inAt' : 'Vào $inAt → Ra $outAt'),
