+import 'dart:async';
+
+import 'package:flutter/material.dart';
+
+import '../../../services/visit_service.dart';
+import 'min_visit_countdown.dart';
+
+/// Mốc giờ check-in + cấu hình thời gian tối thiểu của lượt đang thăm, gắn
+/// quanh màn từng bước (Kiểm tồn, Trưng bày, Ghi chú, Đơn hàng, Khảo sát) để
+/// màn đó hiện đồng hồ mà không cần biết gì về luồng viếng thăm.
+class VisitTimerScope extends InheritedWidget {
+  const VisitTimerScope({
+    super.key,
+    required this.openedAt,
+    required this.config,
+    required super.child,
+  });
+
+  /// Giờ CHECK-IN của lượt (mốc tuyệt đối).
+  final DateTime openedAt;
+  final MinVisitConfig config;
+
+  static VisitTimerScope? maybeOf(BuildContext context) =>
+      context.dependOnInheritedWidgetOfExactType<VisitTimerScope>();
+
+  /// Bọc [child] khi đã có giờ check-in; chưa có → trả nguyên [child].
+  static Widget wrap({
+    required DateTime? openedAt,
+    required MinVisitConfig? config,
+    required Widget child,
+  }) {
+    if (openedAt == null) return child;
+    return VisitTimerScope(
+      openedAt: openedAt,
+      config: config ?? MinVisitConfig.none,
+      child: child,
+    );
+  }
+
+  @override
+  bool updateShouldNotify(VisitTimerScope oldWidget) =>
+      openedAt != oldWidget.openedAt ||
+      config.minMinutes != oldWidget.config.minMinutes;
+}
+
+/// Dòng đồng hồ của màn bước:
+/// - chưa đủ thời gian tối thiểu → `Còn mm:ss mới đủ thời gian check-out` (cam);
+/// - đã đủ / không cấu hình → `Đã ở điểm mm:ss` (xanh), vẫn chạy tiếp.
+///
+/// Mỗi giây tính lại từ [openedAt] (mốc tuyệt đối, offline OK) và chỉ vẽ lại
+/// chính nó — giống quy tắc của [MinVisitCountdown].
+String visitStepTimerText({
+  required DateTime openedAt,
+  required MinVisitConfig config,
+  required DateTime now,
+}) {
+  final elapsed = now.toUtc().difference(openedAt.toUtc());
+  final remaining = Duration(minutes: config.minMinutes) - elapsed;
+  if (config.isActive && remaining > Duration.zero) {
+    return 'Còn ${formatCountdown(remaining)} mới đủ thời gian check-out';
+  }
+  return 'Đã ở điểm ${formatCountdown(elapsed)}';
+}
+
+class VisitStepTimer extends StatefulWidget implements PreferredSizeWidget {
+  const VisitStepTimer({
+    super.key,
+    required this.openedAt,
+    required this.config,
+    DateTime Function()? clock,
+  }) : _clock = clock;
+
+  final DateTime openedAt;
+  final MinVisitConfig config;
+  final DateTime Function()? _clock;
+
+  static const double height = 30;
+
+  /// Thanh đồng hồ cho `AppBar.bottom` — null khi màn không mở từ viếng thăm
+  /// (không có [VisitTimerScope]).
+  static PreferredSizeWidget? maybeBar(BuildContext context) {
+    final scope = VisitTimerScope.maybeOf(context);
+    if (scope == null) return null;
+    return VisitStepTimer(openedAt: scope.openedAt, config: scope.config);
+  }
+
+  @override
+  Size get preferredSize => const Size.fromHeight(height);
+
+  @override
+  State<VisitStepTimer> createState() => _VisitStepTimerState();
+}
+
+class _VisitStepTimerState extends State<VisitStepTimer> {
+  late final DateTime Function() _now = widget._clock ?? DateTime.now;
+  Timer? _timer;
+
+  @override
+  void initState() {
+    super.initState();
+    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
+      if (mounted) setState(() {});
+    });
+  }
+
+  @override
+  void dispose() {
+    _timer?.cancel();
+    super.dispose();
+  }
+
+  @override
+  Widget build(BuildContext context) {
+    final now = _now();
+    final remaining = Duration(minutes: widget.config.minMinutes) -
+        now.toUtc().difference(widget.openedAt.toUtc());
+    final pending = widget.config.isActive && remaining > Duration.zero;
+    final color = pending ? Colors.orange.shade800 : Colors.green.shade700;
+    return Container(
+      key: const Key('visit_step_timer'),
+      height: VisitStepTimer.height,
+      width: double.infinity,
+      color: color.withValues(alpha: 0.1),
+      padding: const EdgeInsets.symmetric(horizontal: 16),
+      child: Row(
+        children: [
+          Icon(Icons.timer_outlined, size: 16, color: color),
+          const SizedBox(width: 6),
+          Expanded(
+            child: Text(
+              visitStepTimerText(
+                openedAt: widget.openedAt,
+                config: widget.config,
+                now: now,
+              ),
+              maxLines: 1,
+              overflow: TextOverflow.ellipsis,
+              style: TextStyle(
+                color: color,
+                fontSize: 13,
+                fontWeight: FontWeight.w600,
+                fontFeatures: const [FontFeature.tabularFigures()],
+              ),
+            ),
+          ),
+        ],
+      ),
+    );
+  }
+}

