+/// Cổng đọc lịch sử từ server (inject để test). Không bao giờ gửi `saleman`:
+/// BE luôn lọc theo người đăng nhập (SPEC §3).
+abstract interface class HistoryRemote {
+  /// `rt.visit/history` → `{ total, items }`.
+  Future<Map<String, dynamic>> visitHistory(Map<String, dynamic> body);
+
+  /// `rt.attendance/my_history` → `{ items }`.
+  Future<Map<String, dynamic>> attendanceHistory(Map<String, dynamic> body);
+}
+
+class ApiHistoryRemote implements HistoryRemote {
+  const ApiHistoryRemote();
+
+  Future<Map<String, dynamic>> _call(
+      String path, Map<String, dynamic> body) async {
+    final response = await ApiClient.post(
+      Uri.parse('${AppConfig.instance.baseUrl}/$path'),
+      headers: {'Content-Type': 'application/json'},
+      body: jsonEncode([body]),
+    );
+    if (response.statusCode != 200) {
+      throw Exception('$path HTTP ${response.statusCode}');
+    }
+    final data = jsonDecode(response.body);
+    if (data is! Map || data['ok'] != true) {
+      throw Exception('$path lỗi: ${data is Map ? data['message'] : ''}');
+    }
+    final result = data['result'];
+    return result is Map<String, dynamic> ? result : const {};
+  }
+
+  @override
+  Future<Map<String, dynamic>> visitHistory(Map<String, dynamic> body) =>
+      _call('rt.visit/history', body);
+
+  @override
+  Future<Map<String, dynamic>> attendanceHistory(Map<String, dynamic> body) =>
+      _call('rt.attendance/my_history', body);
+}
