+        to = DateTime(to.year, to.month, to.day);
+
+  factory DayRange.day(DateTime d) => DayRange(d, d);
+
+  /// Cả tháng hiện tại (gồm ngày tới — đơn nghỉ đã xin cho cuối tháng vẫn hiện).
+  factory DayRange.thisMonth(DateTime now) => DayRange(
+      DateTime(now.year, now.month, 1), DateTime(now.year, now.month + 1, 0));
+
+  final DateTime from;
+  final DateTime to;
+
+  DateTime get start => from;
+  DateTime get endExclusive => to.add(const Duration(days: 1));
+
+  bool contains(DateTime t) {
+    final l = t.toLocal();
+    return !l.isBefore(start) && l.isBefore(endExclusive);
+  }
+
+  Map<String, String> toBody() => {'from': _day.format(from), 'to': _day.format(to)};
+}
+
+/// Lịch sử chấm công + viếng thăm của sale: server là nguồn chính, gộp thêm
+/// bản ghi trên máy CHƯA đồng bộ (serverId null). Mất mạng → chỉ dữ liệu máy.
+/// Chỉ đọc, không ghi gì (SPEC §4.1).
+class HistoryService {
+  HistoryService(this._db, {HistoryRemote? remote})
+      : _remote = remote ?? const ApiHistoryRemote();
+
+  final AppDatabase _db;
+  final HistoryRemote _remote;
+
+  static const pageSize = 50;
+
+  Future<VisitHistoryPage> visits(DayRange range, {int offset = 0}) async {
+    // Bản ghi máy chỉ gộp vào trang đầu (tránh lặp khi "Tải thêm").
+    final local = offset == 0 ? await _localVisits(range) : <VisitHistoryItem>[];
+    try {
+      final res = await _remote.visitHistory({
+        ...range.toBody(),
+        'limit': pageSize,
+        'offset': offset,
+      });
+      // Ghi chú/bước lưu ở máy nhưng chưa lên server (save_step còn trong
+      // outbox) → vẫn hiện ở bản server của cùng lượt.
+      final localBy = {for (final v in local) v.clientUuid: v};
+      final server = [
+        for (final v in _visitItems(res['items']))
+          if (localBy[v.clientUuid] case final l?) v.withLocal(l) else v,
+      ];
+      final known = server.map((v) => v.clientUuid).toSet();
+      final extra = local.where((v) => v.localOnly && !known.contains(v.clientUuid));
+      final items = [...server, ...extra]
+        ..sort((a, b) => b.checkinAt.compareTo(a.checkinAt));
+      final total = res['total'] is num ? (res['total'] as num).toInt() : server.length;
+      return VisitHistoryPage(
+          items: items, total: total, serverCount: server.length);
+    } on Object {
+      return VisitHistoryPage(items: local, total: 0, offline: true);
+    }
+  }
+
+  Future<AttendanceHistoryPage> attendance(DayRange range) async {
+    final local = await _localAttendance(range);
+    try {
+      final res = await _remote.attendanceHistory(range.toBody());
+      final server = (res['items'] is List ? res['items'] as List : const [])
+          .whereType<Map<String, dynamic>>()
+          .map(AttendanceHistoryItem.fromJson)
+          .whereType<AttendanceHistoryItem>()
+          .toList();
+      final known = server.map((a) => a.clientUuid).toSet();
+      final merged = [
+        ...server,
+        ...local.items.where((a) => !known.contains(a.clientUuid)),
+      ];
+      return AttendanceHistoryPage(
+          items: _attachLocalCheckouts(merged, local.unsyncedCheckouts));
+    } on Object {
+      return AttendanceHistoryPage(
+        items: _attachLocalCheckouts(local.items, local.unsyncedCheckouts),
+        offline: true,
+      );
+    }
+  }
+
+  /// Tối đa [limit] ghi chú các lần thăm TRƯỚC tại [customer] (90 ngày, mới
+  /// nhất trước), bỏ lượt [excludeVisitUuid]. Server lỗi → chỉ ghi chú trên máy
+  /// và [PastNotesResult.failed] = true. Chỉ ghi chú của chính sale.
+  Future<PastNotesResult> pastNotes(
+    int customer, {
+    String? excludeVisitUuid,
+    int limit = 5,
+    DateTime? now,
+  }) async {
+    final today = now ?? DateTime.now();
+    // BE giới hạn 31 ngày/lần → 3 lần gọi cho 90 ngày, gọi lần lượt và dừng
+    // sớm khi đã đủ ghi chú.
+    final byUuid = <String, PastVisitNote>{};
+    for (final n in await _localNotes(customer)) {
+      byUuid[n.visitUuid] = n;
+    }
+    // Ghi chú sửa trên máy còn chờ đồng bộ → giữ bản máy, không để bản cũ
+    // trên server đè.
+    final pending = await _pendingNoteVisits();
+    var failed = false;
+    var to = today;
+    for (var i = 0; i < 3; i++) {
+      final from = to.subtract(const Duration(days: 29));
+      try {
+        final res = await _remote.visitHistory({
+          ...DayRange(from, to).toBody(),
+          'customer': customer,
+          'limit': 20,
+        });
+        for (final v in _visitItems(res['items'])) {
+          if (v.note != null && !pending.contains(v.clientUuid)) {
+            byUuid[v.clientUuid] =
+                PastVisitNote(visitUuid: v.clientUuid, at: v.checkinAt, text: v.note!);
+          }
+        }
+      } on Object {
+        failed = true;
+        break;
+      }
+      final have = byUuid.keys.where((k) => k != excludeVisitUuid).length;
+      if (have >= limit) break;
+      to = from.subtract(const Duration(days: 1));
+    }
+    final notes = byUuid.values.where((n) => n.visitUuid != excludeVisitUuid).toList()
+      ..sort((a, b) => b.at.compareTo(a.at));
+    return PastNotesResult(notes.take(limit).toList(), failed: failed);
+  }
+
+  List<VisitHistoryItem> _visitItems(Object? raw) =>
+      (raw is List ? raw : const [])
+          .whereType<Map<String, dynamic>>()
+          .map(VisitHistoryItem.fromJson)
+          .whereType<VisitHistoryItem>()
+          .toList();
+
+  Future<List<VisitHistoryItem>> _localVisits(DayRange range) async {
+    final rows = await (_db.select(_db.visits)
+          ..where((t) =>
+              t.openedAt.isBiggerOrEqualValue(range.start.toUtc()) &
+              t.openedAt.isSmallerThanValue(range.endExclusive.toUtc()) &
+              t.status.isNotIn(const [9]))
+          ..orderBy([(t) => OrderingTerm.desc(t.openedAt)]))
+        .get();
+    if (rows.isEmpty) return [];
+    final uuids = rows.map((r) => r.clientUuid).toList();
+    final custIds = rows.map((r) => r.customer).toSet().toList();
+    // Theo thứ tự lưu → bản ghi chú lưu sau cùng thắng.
+    final steps = await (_db.select(_db.visitSteps)
+          ..where((t) => t.visitUuid.isIn(uuids))
+          ..orderBy([(t) => OrderingTerm.asc(t.localId)]))
+        .get();
+    final pendingNotes = await _pendingNoteVisits();
+    final custs = await (_db.select(_db.customers)
+          ..where((t) => t.id.isIn(custIds)))
+        .get();
+    final custById = {for (final c in custs) c.id: c};
+    final stepsBy = <String, List<String>>{};
+    final noteBy = <String, String>{};
+    for (final s in steps) {
+      (stepsBy[s.visitUuid] ??= []).add(s.step);
+      if (s.step == 'note') {
+        final t = noteTextOf(s.payloadJson);
+        if (t != null) noteBy[s.visitUuid] = t;
+      }
+    }
+    final inDayRoute = await _localDayRouteChecker();
+    return rows.map((r) {
+      final c = custById[r.customer];
+      return VisitHistoryItem(
+        clientUuid: r.clientUuid,
+        customerId: r.customer,
+        customerName: (c?.name.isNotEmpty ?? false) ? c!.name : 'KH #${r.customer}',
+        customerAddress: c?.addressText,
+        // §3.2b: "Trong tuyến" = có lịch tuyến NGÀY check-in. App không gửi
+        // route_line → tự tính từ tuyến trên máy (server có cờ thì bản server
+        // thắng khi gộp).
+        source: VisitSource.infer(
+          isOffroute: r.isOffroute,
+          inDayRoute: inDayRoute(r.customer, r.openedAt),
+        ),
+        status: r.status,
+        outcome: r.outcome,
+        checkinAt: r.openedAt,
+        checkoutAt: r.closedAt,
+        durationMinutes: r.durationMinutes,
+        steps: stepsBy[r.clientUuid] ?? const [],
+        note: noteBy[r.clientUuid],
+        localOnly: r.serverId == null,
+        notePending: pendingNotes.contains(r.clientUuid),
+      );
+    }).toList();
+  }
+
+  /// Các lượt (client_uuid) có `visit.save_step` bước note còn chờ trong outbox.
+  /// KH có trong lịch tuyến (trên máy) vào ngày [at] không — cùng luật
+  /// `selectLinesForDay` của tab Hôm nay offline. Tuyến trên máy là bản HIỆN
+  /// TẠI: đủ cho lượt chưa đồng bộ (thường cùng ngày).
+  Future<bool Function(int customer, DateTime at)> _localDayRouteChecker() async {
+    final routeById = {
+      for (final r in await _db.select(_db.routes).get())
+        r.id: RouteDays(
+          id: r.id,
+          active: r.active,
+          unlimited: r.unlimited,
+          visitWeekdays: r.visitWeekdays,
+        ),
+    };
+    final lines = [
+      for (final l in await _db.select(_db.routeLines).get())
+        RouteLineDays(
+          route: l.route,
+          customer: l.customer,
+          weekdays: l.weekdays,
+          sequence: l.sequence,
+          active: l.active,
+        ),
+    ];
+    final byDow = <int, Set<int>>{};
+    return (customer, at) {
+      final dow = dowOf(at.toLocal());
+      final set = byDow[dow] ??= {
+        for (final d in selectLinesForDay(routeById, lines, dow)) d.customer,
+      };
+      return set.contains(customer);
+    };
+  }
+
+  Future<Set<String>> _pendingNoteVisits() async {
+    final rows = await (_db.select(_db.outbox)
+          ..where((t) =>
+              t.type.equals('visit.save_step') &
+              t.status.equals(OutboxStatus.done).not()))
+        .get();
+    final out = <String>{};
+    for (final r in rows) {
+      try {
+        final p = jsonDecode(r.payloadJson);
+        if (p is! Map || p['step'] != 'note') continue;
+        final v = p['visit']?.toString() ?? '';
+        out.add(v.startsWith(OutboxDispatcher.refPrefix)
+            ? v.substring(OutboxDispatcher.refPrefix.length)
+            : v);
+      } on FormatException {
+        continue;
+      }
+    }
+    return out;
+  }
+
+  Future<List<PastVisitNote>> _localNotes(int customer) async {
+    final visits = await (_db.select(_db.visits)
+          ..where((t) => t.customer.equals(customer)))
+        .get();
+    if (visits.isEmpty) return [];
+    final openedBy = {for (final v in visits) v.clientUuid: v.openedAt};
+    final steps = await (_db.select(_db.visitSteps)
+          ..where((t) =>
+              t.visitUuid.isIn(openedBy.keys.toList()) & t.step.equals('note'))
+          ..orderBy([(t) => OrderingTerm.asc(t.localId)]))
+        .get();
+    return [
+      for (final s in steps)
+        if (noteTextOf(s.payloadJson) case final text?)
+          PastVisitNote(
+            visitUuid: s.visitUuid,
+            at: openedBy[s.visitUuid] ?? s.savedAt,
+            text: text,
+          ),
+    ];
+  }
+
+  Future<_LocalAttendance> _localAttendance(DayRange range) async {
+    final rows = await (_db.select(_db.attendanceRecords)
+          ..where((t) => t.serverId.isNull())
+          ..orderBy([(t) => OrderingTerm.asc(t.at)]))
+        .get();
+    final items = <AttendanceHistoryItem>[];
+    final checkouts = <DateTime>[];
+    for (final r in rows) {
+      switch (r.kind) {
+        case 'check_in':
+          if (range.contains(r.at)) {
+            items.add(AttendanceHistoryItem(
+              clientUuid: r.clientUuid,
+              kind: AttendanceKind.shift,
+              checkInAt: r.at,
+              localOnly: true,
+            ));
+          }
+        case 'check_out':
+          checkouts.add(r.at);
+        case 'leave':
+          final leave = await _localLeave(r);
+          final from = leave.leaveFrom ?? r.at;
+          final to = leave.leaveTo ?? from;
+          // Giao kỳ như BE: from ≤ cuối kỳ & to ≥ đầu kỳ.
+          if (from.toLocal().isBefore(range.endExclusive) &&
+              !to.toLocal().isBefore(range.start)) {
+            items.add(leave);
+          }
+      }
+    }
+    return _LocalAttendance(items, checkouts);
+  }
+
+  /// Đơn nghỉ chưa đồng bộ: chi tiết nằm trong payload outbox.
+  Future<AttendanceHistoryItem> _localLeave(AttendanceRecord r) async {
+    final box = await (_db.select(_db.outbox)
+          ..where((t) => t.clientUuid.equals(r.clientUuid))
+          ..limit(1))
+        .getSingleOrNull();
+    Map<String, dynamic> p = const {};
+    try {
+      final decoded = box == null ? null : jsonDecode(box.payloadJson);
+      if (decoded is Map<String, dynamic>) p = decoded;
+    } on FormatException {
+      p = const {};
+    }
+    DateTime? d(Object? v) => v is String ? DateTime.tryParse(v) : null;
+    return AttendanceHistoryItem(
+      clientUuid: r.clientUuid,
+      kind: AttendanceKind.leave,
+      leaveType: p['type']?.toString(),
+      leaveFrom: d(p['from']),
+      leaveTo: d(p['to']),
+      reason: p['reason']?.toString(),
+      localOnly: true,
+    );
+  }
+
+  /// Giờ ra chưa đồng bộ → gắn vào ca mở gần nhất trước nó. Sắp xếp mới nhất trước.
+  List<AttendanceHistoryItem> _attachLocalCheckouts(
+    List<AttendanceHistoryItem> items,
+    List<DateTime> checkouts,
+  ) {
+    final out = [...items]..sort((a, b) => a.sortAt.compareTo(b.sortAt));
+    for (final co in checkouts) {
+      for (var i = out.length - 1; i >= 0; i--) {
+        final a = out[i];
+        if (a.kind != AttendanceKind.shift || a.checkInAt == null) continue;
+        if (a.checkInAt!.isAfter(co)) continue;
+        if (a.checkOutAt == null) {
+          out[i] = a.copyWith(
+            checkOutAt: co,
+            workedMinutes: co.difference(a.checkInAt!).inMinutes,
+            checkOutLocalOnly: true,
+          );
+        }
+        break;
+      }
+    }
+    out.sort((a, b) => b.sortAt.compareTo(a.sortAt));
+    return out;
+  }
+}
+
+class _LocalAttendance {
+  const _LocalAttendance(this.items, this.unsyncedCheckouts);
+  final List<AttendanceHistoryItem> items;
+  final List<DateTime> unsyncedCheckouts;
+}
+
+class PastNotesResult {
+  const PastNotesResult(this.notes, {this.failed = false});
+  final List<PastVisitNote> notes;
+
+  /// Không tải được từ server (chỉ có ghi chú trên máy).
+  final bool failed;
+}
+
+/// `payload.text` của bước note (JSON) → nội dung đã trim, rỗng → null.
+String? noteTextOf(String payloadJson) {
+  try {
+    final p = jsonDecode(payloadJson);
+    if (p is! Map) return null;
+    final t = p['text']?.toString().trim() ?? '';
+    return t.isEmpty ? null : t;
+  } on FormatException {
+    return null;
+  }
+}

