+import 'dart:convert';
+
+import '../config/app_config.dart';
+import 'api_client.dart';
+
+/// Loại mã sale nhập ở bước 1 màn Tạo KH.
+enum TaxCodeKind { taxCode, cccd }
+
+/// Phân loại + chuẩn hoá mã — khớp BE `btnet/lib/tax_lookup.normalizeLookupCode`.
+/// MST: 10 số | 10-3 | 13 số (→ 10-3). CCCD: 12 số. Sai → null.
+({String code, TaxCodeKind kind})? classifyTaxCode(String raw) {
+  final t = raw.replaceAll(RegExp(r'[\s.]'), '');
+  if (RegExp(r'^\d{12}$').hasMatch(t)) return (code: t, kind: TaxCodeKind.cccd);
+  if (RegExp(r'^\d{10}(-\d{3})?$').hasMatch(t)) {
+    return (code: t, kind: TaxCodeKind.taxCode);
+  }
+  if (RegExp(r'^\d{13}$').hasMatch(t)) {
+    return (
+      code: '${t.substring(0, 10)}-${t.substring(10)}',
+      kind: TaxCodeKind.taxCode,
+    );
+  }
+  return null;
+}
+
+/// Một mục danh mục hành chính BE đã khớp (`{id, name}`).
+class TaxLookupPlace {
+  const TaxLookupPlace(this.id, this.name);
+  final int id;
+  final String name;
+
+  static TaxLookupPlace? fromJson(Object? v) {
+    if (v is! Map) return null;
+    final id = v['id'];
+    if (id is! num) return null;
+    return TaxLookupPlace(id.toInt(), (v['name'] ?? '').toString());
+  }
+}
+
+/// Kết quả `bt.saleman/lookup_tax_code` (SPEC-tra-cuu-mst-cccd §3).
+class TaxLookupResult {
+  const TaxLookupResult({
+    required this.code,
+    required this.kind,
+    required this.found,
+    this.reason,
+    this.name,
+    this.orgType,
+    this.isHousehold = false,
+    this.address,
+    this.status,
+    this.isActive = true,
+    this.line1,
+    this.province,
+    this.ward,
+    this.existingCode,
+    this.existingName,
+    this.source,
+  });
+
+  final String code;
+  final TaxCodeKind kind;
+  final bool found;
+
+  /// `not_found` | `not_configured` | `unavailable` khi [found] = false.
+  final String? reason;
+
+  final String? name;
+  final String? orgType;
+  final bool isHousehold;
+  final String? address;
+  final String? status;
+  final bool isActive;
+
+  /// Địa chỉ đã tách + khớp danh mục (null = không khớp, sale tự chọn).
+  final String? line1;
+  final TaxLookupPlace? province;
+  final TaxLookupPlace? ward;
+
+  /// KH đã dùng mã này (cảnh báo sớm).
+  final String? existingCode;
+  final String? existingName;
+
+  /// 4 trường truy vết nguồn ngoài — gửi lại nguyên khối khi tạo KH.
+  final Map<String, dynamic>? source;
+
+  bool get hasExisting => existingCode != null;
+
+  /// Câu báo ngắn khi không có dữ liệu tự điền.
+  String get missMessage => switch (reason) {
+    'not_found' => 'Không tìm thấy thông tin cho mã này — vui lòng nhập tay',
+    'not_configured' =>
+      'Chưa bật tra cứu MST trên hệ thống — vui lòng nhập tay',
+    _ => 'Không tra cứu được lúc này — vui lòng nhập tay',
+  };
+
+  factory TaxLookupResult.fromJson(Map<String, dynamic> j) {
+    String? str(Object? v) {
+      final t = v?.toString().trim() ?? '';
+      return t.isEmpty ? null : t;
+    }
+
+    final info = j['info'] is Map
+        ? Map<String, dynamic>.from(j['info'] as Map)
+        : const <String, dynamic>{};
+    final addr = j['address'] is Map
+        ? Map<String, dynamic>.from(j['address'] as Map)
+        : const <String, dynamic>{};
+    final existing = j['existing'] is Map ? j['existing'] as Map : null;
+    final source = j['source'] is Map
+        ? Map<String, dynamic>.from(j['source'] as Map)
+        : null;
+    return TaxLookupResult(
+      code: (j['code'] ?? '').toString(),
+      kind: j['kind'] == 'cccd' ? TaxCodeKind.cccd : TaxCodeKind.taxCode,
+      found: j['found'] == true,
+      reason: str(j['reason']),
+      name: str(info['name']),
+      orgType: str(info['org_type']),
+      isHousehold: info['is_household'] == true,
+      address: str(info['address']),
+      status: str(info['status']),
+      isActive: info['is_active'] != false,
+      line1: str(addr['line1']),
+      province: TaxLookupPlace.fromJson(addr['province']),
+      ward: TaxLookupPlace.fromJson(addr['ward']),
+      existingCode: existing == null ? null : str(existing['code']),
+      existingName: existing == null ? null : str(existing['name']),
+      source: source,
+    );
+  }
+
+  /// Không gọi được BE (offline/lỗi mạng) — vẫn cho sale nhập tay.
+  factory TaxLookupResult.offline(String code, TaxCodeKind kind) =>
+      TaxLookupResult(
+        code: code,
+        kind: kind,
+        found: false,
+        reason: 'unavailable',
+      );
+}
+
+/// Cổng tra cứu (inject để test).
+abstract interface class TaxLookup {
+  /// Ném [FormatException] nếu BE từ chối mã (sai định dạng).
+  Future<TaxLookupResult> lookup(String code, TaxCodeKind kind);
+}
+
+/// Triển khai `bt.saleman/lookup_tax_code` qua [ApiClient].
+class ApiTaxLookup implements TaxLookup {
+  const ApiTaxLookup();
+
+  @override
+  Future<TaxLookupResult> lookup(String code, TaxCodeKind kind) async {
+    final url = Uri.parse(
+      '${AppConfig.instance.baseUrl}/bt.saleman/lookup_tax_code',
+    );
+    final Map<String, dynamic> data;
+    try {
+      final response = await ApiClient.post(
+        url,
+        headers: {'Content-Type': 'application/json'},
+        body: jsonEncode([
+          {'code': code},
+        ]),
+        timeout: const Duration(seconds: 15),
+      );
+      if (response.statusCode != 200) {
+        return TaxLookupResult.offline(code, kind);
+      }
+      data = jsonDecode(response.body) as Map<String, dynamic>;
+    } on Object {
+      // Mất mạng / timeout / body hỏng → không chặn tạo KH.
+      return TaxLookupResult.offline(code, kind);
+    }
+    if (data['ok'] != true) {
+      // Lỗi nghiệp vụ duy nhất của API: mã sai định dạng.
+      throw FormatException(
+        (data['message'] as String?) ?? 'Mã số thuế/CCCD không hợp lệ',
+      );
+    }
+    final result = data['result'];
+    return result is Map<String, dynamic>
+        ? TaxLookupResult.fromJson(result)
+        : TaxLookupResult.offline(code, kind);
+  }
+}

