+/// Đường dẫn ảnh đang hiển thị ở ảnh thu nhỏ.
+String? shownPhotoPath(WidgetTester tester) {
+  final finder = find.descendant(
+    of: find.byKey(const Key('checkin_photo_preview')),
+    matching: find.byType(Image),
+  );
+  if (finder.evaluate().isEmpty) return null;
+  final provider = tester.widget<Image>(finder).image;
+  final file = provider is ResizeImage ? provider.imageProvider : provider;
+  return (file as FileImage).file.path;
+}
