+import 'package:btnet_saleman/services/tax_lookup_service.dart';
+import 'package:flutter/material.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+/// Tra cứu giả: mặc định "không tìm thấy" (form để trống, mã vào ô MST/CCCD).
+class FakeTaxLookup implements TaxLookup {
+  FakeTaxLookup([this.json]);
+
+  /// Body `result` BE trả về; null → not_found.
+  final Map<String, dynamic>? json;
+  final List<String> calls = [];
+
+  @override
+  Future<TaxLookupResult> lookup(String code, TaxCodeKind kind) async {
+    calls.add(code);
+    return TaxLookupResult.fromJson(json ??
+        {
+          'code': code,
+          'kind': kind == TaxCodeKind.cccd ? 'cccd' : 'tax_code',
+          'found': false,
+          'reason': 'not_found',
+        });
+  }
+}
+
+/// Qua bước 1 màn Tạo KH: nhập mã → Tra cứu → form bước 2.
+Future<void> passIdentityStep(WidgetTester tester,
+    {String code = '0101248141'}) async {
+  await tester.enterText(find.byKey(const Key('tax-lookup-input')), code);
+  await tester.tap(find.widgetWithText(FilledButton, 'Tra cứu'));
+  await tester.pumpAndSettle();
+}
